function ParticlePoolMgr:PlayEffect()
    local parameters = self.parameters
    local poolSize   = parameters.poolSize
    if #self.pool < poolSize then
        self.lastIndex = self.lastIndex + 1
        self:Play(parameters, self.lastIndex)
    else
        if self.lastIndex >= poolSize then
            self.lastIndex = 1
        else
            self.lastIndex = self.lastIndex + 1
        end
        self:StopAndClearCoByIndex(self.lastIndex)
        local go = self.pool[self.lastIndex]
        KTool.SetActive(go.gameObject, false)
        self:Play(parameters, self.lastIndex)
    end
end

function ParticlePoolMgr:Play(parameters, index)
    local prefabPath = parameters.prefabPath
    local activeTime = parameters.activeTime
    local parent = self.controller.gameObject
    local co = cs_coroutine.start(function()
        local go = self.pool[index]
        if isNull(go) then
            go = GameUtils.LoadBundleAsync(prefabPath, parent, false, true)
            if isNull(go) then return end
            -- table.insert(self.loaders, loader)
            self.pool[index] = go
            if self.initCb then
                self.initCb()
            end
        else
            KTool.SetActive(go.gameObject, true)
        end
        if self.playCb then
            self.playCb()
        end

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(activeTime))

        KTool.SetActive(go.gameObject, false)
        self.cos[index] = nil
    end)
    self.cos[index] = co
end

function ParticlePoolMgr:StopAndClearCoByIndex(index)
    local co = self.cos[index]
    if isNull(co) then return end
    cs_coroutine.stop(co)
    self.cos[index] = nil
end

